package lanse.worldwarchess.shared.core.gamemode;

import javax.swing.*;
import java.awt.*;

public class GameModeSelector extends JDialog {

    //This class was generated by AI because I was sick and dying and could not be bothered to write all this ui crap.

    private GameModeType selectedType;

    public GameModeSelector(Window owner, GameModeType current) {
        super(owner, "Select Game Mode", ModalityType.APPLICATION_MODAL);
        setSize(420, 260);
        setLocationRelativeTo(owner);
        setLayout(new BorderLayout(8, 8));

        DefaultListModel<GameModeType> model = new DefaultListModel<>();
        for (GameModeType t : GameModeType.values()) {
            model.addElement(t);
        }

        JList<GameModeType> list = new JList<>(model);
        list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        list.setSelectedValue(current, true);
        list.setCellRenderer((lst, value, idx, sel, focus) -> {
            JLabel lbl = new JLabel(value.getDisplayName());
            lbl.setOpaque(true);
            lbl.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
            lbl.setBackground(sel ? new Color(70, 70, 90) : new Color(45, 45, 45));
            lbl.setForeground(Color.WHITE);
            return lbl;
        });

        JTextArea description = new JTextArea();
        description.setEditable(false);
        description.setLineWrap(true);
        description.setWrapStyleWord(true);
        description.setBackground(new Color(30, 30, 30));
        description.setForeground(Color.WHITE);
        description.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

        list.addListSelectionListener(e -> {
            GameModeType t = list.getSelectedValue();
            if (t != null) description.setText(t.getDescription());
        });

        // Initialize description
        list.setSelectedIndex(list.getSelectedIndex());

        JPanel center = new JPanel(new GridLayout(1, 2, 8, 0));
        center.add(new JScrollPane(list));
        center.add(new JScrollPane(description));
        add(center, BorderLayout.CENTER);

        JButton confirm = new JButton("Confirm");
        JButton cancel = new JButton("Cancel");

        confirm.addActionListener(e -> {
            selectedType = list.getSelectedValue();
            dispose();
        });

        cancel.addActionListener(e -> {
            selectedType = null;
            dispose();
        });

        JPanel bottom = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        bottom.add(confirm);
        bottom.add(cancel);

        add(bottom, BorderLayout.SOUTH);
    }

    public GameModeType getSelectedType() {
        return selectedType;
    }
}
